<script lang="ts">
 import {onMount} from 'svelte';import {authClient} from '$lib/auth-client';import {translator} from '$lib/app-i18n';let {data}=$props();let t=$derived(translator(data.lang)),email=$state(''),password=$state(''),token=$state(''),message=$state(''),busy=$state(false);onMount(()=>{token=new URL(location.href).searchParams.get('token')??'';history.replaceState(null,'','/reset');});
 async function submit(){busy=true;try{const result=token?await authClient.resetPassword({token,newPassword:password}):await authClient.requestPasswordReset({email,redirectTo:location.origin+'/reset'});message=result.error?t('AUTH_REQUEST_FAILED'):t(token?'passwordChanged':'resetEmailSent');if(!result.error&&token)token='';}catch{message=t('CONNECTION_FAILED');}finally{busy=false;}}
</script>
<main><h1>Vinea · {t('resetPassword')}</h1>{#if data.mailEnabled||token}<form onsubmit={(e)=>{e.preventDefault();submit();}}>{#if token}<label>{t('password')}<input type="password" required minlength="12" maxlength="128" bind:value={password} autocomplete="new-password" /></label>{:else}<label>{t('email')}<input type="email" required bind:value={email} autocomplete="email" /></label>{/if}<button disabled={busy}>{t('resetPassword')}</button></form>{:else}<p>{t('MAIL_NOT_CONFIGURED')}</p>{/if}<p role="status">{message}</p><a href="/login">{t('signin')}</a></main>
<style>main{max-width:480px;margin:10vh auto;padding:25px;font-family:system-ui}form,label{display:grid;gap:12px}form{margin:24px 0}input,button{padding:14px;border-radius:7px;border:1px solid #d7ded5}button{background:#285741;color:white}</style>
